WITH metrics AS (SELECT id, store_name, MAX(sqft) OVER (PARTITION BY city) AS city_max_sqft, CUME_DIST() OVER (ORDER BY sqft NULLS FIRST) AS sqft_cume_dist, CUME_DIST() OVER w_running AS sqft_cume_dist_2 FROM stores WHERE region IN ('East', 'West') WINDOW w_running AS (ORDER BY sqft DESC NULLS FIRST)) SELECT id, store_name, sqft_cume_dist, sqft_cume_dist_2, CASE WHEN store_name RLIKE '^(Siam Flagship|Downtown Express)$' THEN 'EXTENDED' WHEN store_name RLIKE '^(Airport Kiosk|Mall Central)$' THEN 'CORE' ELSE 'PRIORITY' END AS store_name_zone FROM metrics;
